sha256_file() {
  local file=$1 output

  # SHA-256 is already part of the archive trust boundary, so reuse it for
  # idempotence instead of adding a hidden dependency on diffutils' `cmp`.
  # Minimal Arch and other bootstrap environments may provide one checksum
  # implementation but no general-purpose byte-comparison utility.
  if command -v sha256sum >/dev/null 2>&1; then
    output=$(sha256sum "$file") || die "cannot hash file: $file"
  else
    command -v shasum >/dev/null 2>&1 ||
      die 'neither sha256sum nor shasum is available'
    output=$(shasum -a 256 "$file") || die "cannot hash file: $file"
  fi
  printf '%s\n' "${output%% *}"
}

