    /) die "$label must not be the filesystem root" ;;
    *//* | */./* | */. | */../* | */..)
      die "$label must not contain empty or dot path segments: $path"
      ;;
  esac
  while [[ "$path" == */ ]]; do
    path=${path%/}
  done
  printf '%s\n' "$path"
}

