physical_path_through_existing_ancestor() {
  local candidate=$1 probe suffix='' leaf physical
  probe=$candidate

  # The final path often does not exist on a first install. Resolve the deepest
  # directory that does exist with physical pwd semantics, then append only the
  # still-missing lexical suffix. This catches an alias in any ancestor without
  # requiring user destinations themselves to exist in advance.
