    leaf=${probe##*/}
    suffix=/$leaf$suffix
    probe=${probe%/*}
    [[ -n "$probe" ]] || probe=/
  done
  physical=$(cd "$probe" 2>/dev/null && pwd -P) ||
    die "cannot resolve destination ancestor: $candidate"
  printf '%s%s\n' "${physical%/}" "$suffix"
}

physical_stable_root=$(physical_path_through_existing_ancestor "$stable_root")
physical_control_root=$(physical_path_through_existing_ancestor "$control_root")

reject_reserved_destination() {
