metadata_string() {
  metadata_file=$1
  key=$2
  sed -n 's/^[[:space:]]*"'"$key"'"[[:space:]]*:[[:space:]]*"\([^"]*\)"[[:space:]]*,\{0,1\}[[:space:]]*$/\1/p' \
    "$metadata_file"
}

metadata_number() {
  metadata_file=$1
  key=$2
  sed -n 's/^[[:space:]]*"'"$key"'"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\)[[:space:]]*,\{0,1\}[[:space:]]*$/\1/p' \
    "$metadata_file"
}

validate_metadata_identity() {
  candidate=$1
  metadata_schema=$(metadata_number "$candidate" schema)
  metadata_repo=$(metadata_string "$candidate" repo)
  metadata_platform=$(metadata_string "$candidate" artifact_platform)
  metadata_version=$(metadata_string "$candidate" version)
  metadata_tag=$(metadata_string "$candidate" tag)
  metadata_commit=$(metadata_string "$candidate" commit)
  metadata_method=$(metadata_string "$candidate" method)
