    die "release metadata schema is not supported: $metadata_schema"
  [[ "$metadata_repo" == "$release_repo" ]] ||
    die "release metadata repository mismatch: $metadata_repo"
  [[ "$metadata_platform" == "$release_platform" ]] ||
    die "release metadata platform mismatch: $metadata_platform"
