    "$metadata_tag" == "$release_version" ]] ||
    die 'release metadata version does not match the archive name'
  [[ "$metadata_method" == release ]] ||
    die "release metadata method is not release: $metadata_method"
  [[ "$metadata_commit" =~ ^[0-9a-f]{8,}$ &&
    "${metadata_commit:0:8}" == "${release_version##*-}" ]] ||
    die 'release metadata commit does not match the release version'
}

