        die "existing release tree differs at $relative"
      extracted_digest=$(sha256_file "$extracted_entry")
      existing_digest=$(sha256_file "$existing_entry")
      [[ "$extracted_digest" == "$existing_digest" ]] ||
        die "existing release tree differs at $relative"
